1	using Microsoft.EntityFrameworkCore;
2	using seed_b_backend.Api.Data;
3	using seed_b_backend.Api.Data.Entities;
4	using seed_b_backend.Api.Services;
5	
6	namespace seed_b_backend.Tests.Services;
7	
8	public class ProductQueryServiceTests
9	{
10	    private static AppDbContext CreateContext()
11	    {
12	        var options = new DbContextOptionsBuilder<AppDbContext>()
13	            .UseInMemoryDatabase(Guid.NewGuid().ToString())
14	            .Options;
15	
16	        return new AppDbContext(options);
17	    }
18	
19	    private static void SeedProducts(AppDbContext db, int count)
20	    {
21	        db.Categories.Add(new Category { Id = "C1", Name = "Kategorie 1" });
22	        db.Subcategories.Add(new Subcategory { Id = "S1", Name = "Unterkategorie 1", CategoryId = "C1" });
23	        db.Suppliers.Add(new Supplier { Id = "L1", Name = "Lieferant 1" });
24	
25	        for (var i = 1; i <= count; i++)
26	        {
27	            var id = $"P{i:D2}";
28	            db.Products.Add(new Product
29	            {
30	                Id = id,
31	                Name = $"Produkt {i:D2}",
32	                Description = "Beschreibung",
33	                SubcategoryId = "S1",
34	                Attributes = "{}"
35	            });
36	            db.Offers.Add(new Offer { ProductId = id, SupplierId = "L1", Price = 10m + i });
37	        }
38	
39	        db.SaveChanges();
40	    }
41	
42	    private static void SeedTwoCategories(AppDbContext db)
43	    {
44	        db.Categories.Add(new Category { Id = "C1", Name = "Kategorie 1" });
45	        db.Categories.Add(new Category { Id = "C2", Name = "Kategorie 2" });
46	        db.Subcategories.Add(new Subcategory { Id = "S1a", Name = "Unterkategorie 1a", CategoryId = "C1" });
47	        db.Subcategories.Add(new Subcategory { Id = "S1b", Name = "Unterkategorie 1b", CategoryId = "C1" });
48	        db.Subcategories.Add(new Subcategory { Id = "S2a", Name = "Unterkategorie 2a", CategoryId = "C2" });
49	        db.Suppliers.Add(new Supplier { Id = "L1", Name = "Lieferant 1" });
50	
51	        AddProducts(db, "S1a", 2);
52	        AddProducts(db, "S1b", 3);
53	        AddProducts(db, "S2a", 2);
54	
55	        db.SaveChanges();
56	    }
57	
58	    private static void AddProducts(AppDbContext db, string subcategoryId, int count)
59	    {
60	        for (var i = 1; i <= count; i++)
61	        {
62	            var id = $"P-{subcategoryId}-{i:D2}";
63	            db.Products.Add(new Product
64	            {
65	                Id = id,
66	                Name = $"Produkt {subcategoryId} {i:D2}",
67	                Description = "Beschreibung",
68	                SubcategoryId = subcategoryId,
69	                Attributes = "{}"
70	            });
71	            db.Offers.Add(new Offer { ProductId = id, SupplierId = "L1", Price = 10m + i });
72	        }
73	    }
74	
75	    [Fact]
76	    public async Task GetProductsAsync_FilteredByCategoryId_ReturnsOnlyProductsFromItsSubcategories()
77	    {
78	        await using var db = CreateContext();
79	        SeedTwoCategories(db);
80	        var service = new ProductQueryService(db);
81	
82	        var result = await service.GetProductsAsync(1, categoryId: "C1");
83	
84	        Assert.Equal(5, result.TotalCount);
85	        Assert.All(result.Items, item => Assert.StartsWith("Produkt S1", item.Name));
86	    }
87	
88	    [Fact]
89	    public async Task GetProductsAsync_FilteredBySubcategoryId_ReturnsOnlyProductsFromThatSubcategory()
90	    {
91	        await using var db = CreateContext();
92	        SeedTwoCategories(db);
93	        var service = new ProductQueryService(db);
94	
95	        var result = await service.GetProductsAsync(1, subcategoryId: "S1a");
96	
97	        Assert.Equal(2, result.TotalCount);
98	        Assert.All(result.Items, item => Assert.StartsWith("Produkt S1a", item.Name));
99	    }
100	
101	    [Fact]
102	    public async Task GetProductsAsync_NoFilter_ReturnsProductsFromAllCategories()
103	    {
104	        await using var db = CreateContext();
105	        SeedTwoCategories(db);
106	        var service = new ProductQueryService(db);
107	
108	        var result = await service.GetProductsAsync(1);
109	
110	        Assert.Equal(7, result.TotalCount);
111	    }
112	
113	    [Fact]
114	    public async Task GetProductsAsync_CategoryIdAndSubcategoryIdBothSet_SubcategoryIdTakesPrecedence()
115	    {
116	        await using var db = CreateContext();
117	        SeedTwoCategories(db);
118	        var service = new ProductQueryService(db);
119	
120	        var result = await service.GetProductsAsync(1, categoryId: "C2", subcategoryId: "S1a");
121	
122	        Assert.Equal(2, result.TotalCount);
123	        Assert.All(result.Items, item => Assert.StartsWith("Produkt S1a", item.Name));
124	    }
125	
126	    [Fact]
127	    public async Task GetProductsAsync_UnknownCategoryId_ReturnsEmptyResultWithoutError()
128	    {
129	        await using var db = CreateContext();
130	        SeedTwoCategories(db);
131	        var service = new ProductQueryService(db);
132	
133	        var result = await service.GetProductsAsync(1, categoryId: "C9");
134	
135	        Assert.Empty(result.Items);
136	        Assert.Equal(0, result.TotalCount);
137	        Assert.Equal(0, result.TotalPages);
138	    }
139	
140	    [Fact]
141	    public async Task GetProductsAsync_UnknownSubcategoryId_ReturnsEmptyResultWithoutError()
142	    {
143	        await using var db = CreateContext();
144	        SeedTwoCategories(db);
145	        var service = new ProductQueryService(db);
146	
147	        var result = await service.GetProductsAsync(1, subcategoryId: "S9");
148	
149	        Assert.Empty(result.Items);
150	        Assert.Equal(0, result.TotalCount);
151	        Assert.Equal(0, result.TotalPages);
152	    }
153	
154	    [Fact]
155	    public async Task GetProductsAsync_CategoryFilterCombinedWithPagination_SplitsFilteredResultsAcrossTwoPages()
156	    {
157	        await using var db = CreateContext();
158	        db.Categories.Add(new Category { Id = "C1", Name = "Kategorie 1" });
159	        db.Categories.Add(new Category { Id = "C2", Name = "Kategorie 2" });
160	        db.Subcategories.Add(new Subcategory { Id = "S1", Name = "Unterkategorie 1", CategoryId = "C1" });
161	        db.Subcategories.Add(new Subcategory { Id = "S2", Name = "Unterkategorie 2", CategoryId = "C2" });
162	        db.Suppliers.Add(new Supplier { Id = "L1", Name = "Lieferant 1" });
163	        AddProducts(db, "S1", 25);
164	        AddProducts(db, "S2", 3);
165	        db.SaveChanges();
166	        var service = new ProductQueryService(db);
167	
168	        var page1 = await service.GetProductsAsync(1, categoryId: "C1");
169	        var page2 = await service.GetProductsAsync(2, categoryId: "C1");
170	
171	        Assert.Equal(25, page1.TotalCount);
172	        Assert.Equal(2, page1.TotalPages);
173	        Assert.Equal(20, page1.Items.Count);
174	        Assert.Equal(5, page2.Items.Count);
175	        Assert.Empty(page1.Items.Select(i => i.Id).Intersect(page2.Items.Select(i => i.Id)));
176	    }
177	
178	    [Fact]
179	    public async Task GetProductsAsync_With25Products_Page1HasTwentyItemsAndCorrectMetadata()
180	    {
181	        await using var db = CreateContext();
182	        SeedProducts(db, 25);
183	        var service = new ProductQueryService(db);
184	
185	        var result = await service.GetProductsAsync(1);
186	
187	        Assert.Equal(20, result.Items.Count);
188	        Assert.Equal(25, result.TotalCount);
189	        Assert.Equal(2, result.TotalPages);
190	    }
191	
192	    [Fact]
193	    public async Task GetProductsAsync_With25Products_Page2HasRemainingFiveItems()
194	    {
195	        await using var db = CreateContext();
196	        SeedProducts(db, 25);
197	        var service = new ProductQueryService(db);
198	
199	        var result = await service.GetProductsAsync(2);
200	
201	        Assert.Equal(5, result.Items.Count);
202	        Assert.Equal(25, result.TotalCount);
203	        Assert.Equal(2, result.TotalPages);
204	    }
205	
206	    [Fact]
207	    public async Task GetProductsAsync_With25Products_PagesAreSortedByNameAndDoNotOverlap()
208	    {
209	        await using var db = CreateContext();
210	        SeedProducts(db, 25);
211	        var service = new ProductQueryService(db);
212	
213	        var page1 = await service.GetProductsAsync(1);
214	        var page2 = await service.GetProductsAsync(2);
215	
216	        var page1Names = page1.Items.Select(i => i.Name).ToList();
217	        var page2Names = page2.Items.Select(i => i.Name).ToList();
218	
219	        Assert.Equal(page1Names.OrderBy(n => n, StringComparer.Ordinal), page1Names);
220	        Assert.Equal(page2Names.OrderBy(n => n, StringComparer.Ordinal), page2Names);
221	        Assert.Empty(page1Names.Intersect(page2Names));
222	
223	        var allNames = page1Names.Concat(page2Names).ToList();
224	        var expectedNames = Enumerable.Range(1, 25).Select(i => $"Produkt {i:D2}").ToList();
225	        Assert.Equal(expectedNames, allNames);
226	    }
227	
228	    [Fact]
229	    public async Task GetProductsAsync_ProductWithMultipleOffers_MinPriceIsLowestOffer()
230	    {
231	        await using var db = CreateContext();
232	        db.Categories.Add(new Category { Id = "C1", Name = "Kategorie 1" });
233	        db.Subcategories.Add(new Subcategory { Id = "S1", Name = "Unterkategorie 1", CategoryId = "C1" });
234	        db.Suppliers.Add(new Supplier { Id = "L1", Name = "Lieferant 1" });
235	        db.Suppliers.Add(new Supplier { Id = "L2", Name = "Lieferant 2" });
236	        db.Products.Add(new Product { Id = "P1", Name = "Produkt 1", Description = "d", SubcategoryId = "S1", Attributes = "{}" });
237	        db.Offers.Add(new Offer { ProductId = "P1", SupplierId = "L1", Price = 30m });
238	        db.Offers.Add(new Offer { ProductId = "P1", SupplierId = "L2", Price = 12.5m });
239	        await db.SaveChangesAsync();
240	        var service = new ProductQueryService(db);
241	
242	        var result = await service.GetProductsAsync(1);
243	
244	        Assert.Equal(12.5m, result.Items.Single().MinPrice);
245	    }
246	
247	    [Theory]
248	    [InlineData(0)]
249	    [InlineData(-5)]
250	    public async Task GetProductsAsync_PageZeroOrNegative_IsTreatedAsPageOne(int page)
251	    {
252	        await using var db = CreateContext();
253	        SeedProducts(db, 25);
254	        var service = new ProductQueryService(db);
255	
256	        var result = await service.GetProductsAsync(page);
257	
258	        Assert.Equal(1, result.Page);
259	        Assert.Equal(20, result.Items.Count);
260	    }
261	
262	    [Fact]
263	    public async Task GetProductsAsync_PageBeyondLastPage_ReturnsEmptyItemsWithCorrectMetadata()
264	    {
265	        await using var db = CreateContext();
266	        SeedProducts(db, 25);
267	        var service = new ProductQueryService(db);
